%[text] Cruise control response
m = 1300;
b = 250;

kp0 = 1;
ki0 = 1;

[S,closedLoop] = cruiseResponse(m,b,kp0,ki0) %[output:21a83631] %[output:81308e4b]

step(closedLoop) %[output:06887afc]

%%
%[text] Cruise control unconstrained optimization
% Set up the optimization
P0 = [kp0 ki0];
optimFunc = @(P) objFunc(P,m,b);

% Do a pattern search
tic
P = patternsearch(optimFunc,P0) %[output:63f256dc] %[output:8b5430f8]
toc %[output:6baab6fb]

% Look at the result
optimFunc(P) %[output:59f55cf4]
[S,closedLoop] = cruiseResponse(m,b,P(1),P(2)) %[output:885c22c1] %[output:4a04d04d]
closedLoop %[output:6ce61bce]
step(closedLoop) %[output:372560ff]

%%
%%
%[text] ## Help us Improve
%[text] [Share your feedback](<matlab: ShareFeedback>) to help us improve this module.
function [obj] = objFunc(P,m,b)
    [S,~] = cruiseResponse(m,b,P(1),P(2));
    obj = S.RiseTime^2;
end

function [S,closedLoop] = cruiseResponse(m,b,kp,ki)

    % Set up the transfer functions
    plant = tf(1,[m b]);
    controller = pid(kp,ki,0);
    
    % Feedback transfer function
    closedLoop = feedback(plant*controller,1);

    % Get the step response characteristics
    S = stepinfo(closedLoop);
    
end

